--
-- Table structure for table `monthly_strategy_activations`
--

DROP TABLE IF EXISTS `monthly_strategy_activations`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `monthly_strategy_activations` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `annual_goal_id` int(11) NOT NULL,
  `department_id` int(11) NOT NULL,
  `year` varchar(50) NOT NULL,
  `month` varchar(50) NOT NULL,
  `active` enum('YES','NO') DEFAULT 'NO',
  `activated_by` int(11) DEFAULT NULL,
  `activated_at` datetime DEFAULT current_timestamp(),
  `updated_by` int(11) DEFAULT NULL,
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_activation` (`annual_goal_id`,`department_id`,`year`,`month`),
  KEY `department_id` (`department_id`),
  KEY `activated_by` (`activated_by`),
  KEY `updated_by` (`updated_by`),
  KEY `idx_msa_year_month_active` (`year`,`month`,`active`,`annual_goal_id`),
  KEY `idx_msa_goal_year_month` (`annual_goal_id`,`year`,`month`,`active`),
  CONSTRAINT `monthly_strategy_activations_ibfk_1` FOREIGN KEY (`annual_goal_id`) REFERENCES `annual_goals` (`id`) ON DELETE CASCADE,
  CONSTRAINT `monthly_strategy_activations_ibfk_2` FOREIGN KEY (`department_id`) REFERENCES `departments` (`id`) ON DELETE CASCADE,
  CONSTRAINT `monthly_strategy_activations_ibfk_3` FOREIGN KEY (`activated_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `monthly_strategy_activations_ibfk_4` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=2871 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

