--
-- Table structure for table `monthly_submissions`
--

DROP TABLE IF EXISTS `monthly_submissions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `monthly_submissions` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `department_id` int(11) NOT NULL,
  `year` varchar(50) NOT NULL,
  `month` varchar(50) NOT NULL,
  `deadline_at` datetime NOT NULL,
  `submitted_at` datetime DEFAULT NULL,
  `status` varchar(50) NOT NULL DEFAULT 'DRAFT',
  `submission_channel` varchar(50) NOT NULL DEFAULT 'WEB',
  `submitted_by` int(11) DEFAULT NULL,
  `approval_status` varchar(50) NOT NULL DEFAULT 'PENDING',
  `gm_feedback` text DEFAULT NULL,
  `gm_feedback_at` datetime DEFAULT NULL,
  `remarks` text DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_dept_period` (`department_id`,`year`,`month`),
  KEY `idx_dept` (`department_id`),
  KEY `idx_period` (`year`,`month`),
  KEY `idx_msub_dept_period` (`department_id`,`year`,`month`),
  KEY `idx_msub_period` (`year`,`month`)
) ENGINE=InnoDB AUTO_INCREMENT=32 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

